// ─── EDIT THESE LINES ───
const PUBLIC_APP_URL = 'https://crm-agent-bot-hj5k.vercel.app';
const INGEST_SECRET = 'PASTE_YOUR_INGEST_SECRET_FROM_VERCEL';
// Only cache the most recent N months in Redis (keeps storage bounded so the
// sync always finishes and never exceeds the KV size limit). Older months are
// read live from Google Sheets on demand. Set 0 to sync ALL months.
const RECENT_MONTHS = 4;
// Optional: sync only one month, e.g. '2026-06'. Leave '' to use RECENT_MONTHS.
const ONLY_PERIOD = '';
// ────────────────────────

const onlyPeriod = String(ONLY_PERIOD || '').trim();
return [{
  json: {
    publicAppUrl: String(PUBLIC_APP_URL || '').trim().replace(/\/+$/, ''),
    ingestSecret: String(INGEST_SECRET || '').trim(),
    recentMonths: onlyPeriod ? 0 : (Number(RECENT_MONTHS) || 0),
    onlyPeriod,
  },
}];

const config = $('App Config').item.json;
const sources = Array.isArray($json.sources) ? $json.sources : [];
const onlyPeriod = String(config.onlyPeriod || '').trim();
const filtered = onlyPeriod
  ? sources.filter((source) => String(source.period || '') === onlyPeriod)
  : sources;

if (!filtered.length) {
  throw new Error(
    onlyPeriod
      ? `No sources found for period ${onlyPeriod}. Check Bot Authority.`
      : 'No sources returned from /api/sources. Check GOOGLE_AUTHORITY_SPREADSHEET_ID on Vercel.'
  );
}

return filtered.map((source) => ({ json: source }));

const body = $json || {};
const source = $('Loop Each Source').item.json || {};
const result = Array.isArray(body.results) ? body.results[0] : null;
return [{
  json: {
    sourceKey: source.sourceKey || result?.sourceKey || null,
    office: source.office || null,
    period: source.period || null,
    ok: Boolean(body.ok) && !result?.error,
    error: result?.error || body.error || null,
    stored: Number(result?.stored || 0),
    ftdStored: Number(result?.ftdStored || 0),
    infoStored: Number(result?.infoStored || 0),
    persisted: Boolean(body.persisted),
  },
}];

const items = $input.all().map((item) => item.json || {});
const synced = items.filter((item) => item.ok);
const failed = items.filter((item) => !item.ok);
const totalRows = synced.reduce((sum, item) => sum + Number(item.stored || 0), 0);
return [{
  json: {
    ok: failed.length === 0 && synced.length > 0,
    syncedCount: synced.length,
    failedCount: failed.length,
    totalLeadRows: totalRows,
    persisted: synced.some((item) => item.persisted),
    failures: failed.map((item) => ({ sourceKey: item.sourceKey, error: item.error })),
    sample: synced.slice(0, 8).map((item) => ({
      sourceKey: item.sourceKey,
      stored: item.stored,
      ftdStored: item.ftdStored,
      infoStored: item.infoStored,
    })),
  },
}];
